package com.bank.training;

import java.util.*;
import java.util.logging.*;

public class TrainingDemo {
    private static final Logger log = Logger.getLogger("Training");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", "Trading", "Mumbai"),
            new Employee("Sneha", "Trading", "Bangalore"),
            new Employee("Rohit", "Trading", "Mumbai"),   // duplicate city for Trading
            new Employee("Priya", "Risk", "Mumbai"),
            new Employee("Neha", "Risk", "Pune"));
        TrainingPlannerService service = new TrainingPlannerService();

        Map<String, Set<String>> cities = service.citiesByDepartment(employees);
        cities.forEach((dept, set) -> log.info(() -> dept + " -> " + set));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final String city;
    Employee(String name, String department, String city) {
        this.name = name; this.department = department; this.city = city;
    }
    String getDepartment() { return department; }
    String getCity() { return city; }
}

// ─── Would be in service/TrainingPlannerService.java ───
class TrainingPlannerService {
    // groupingBy department, then mapping each employee to city, collected into a Set (distinct)
    Map<String, Set<String>> citiesByDepartment(List<Employee> employees) {
        return employees.stream().collect(
            java.util.stream.Collectors.groupingBy(
                Employee::getDepartment,
                java.util.stream.Collectors.mapping(
                    Employee::getCity,
                    java.util.stream.Collectors.toSet())));  // distinct cities
    }
}
